def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    bg=max(set(v for row in a for v in row), key=lambda c:sum(row.count(c) for row in a))
    seen=set()
    for y in range(h):
      for x in range(w):
        c=a[y][x]
        if c==bg or (y,x) in seen: continue
        stack=[(y,x)]; seen.add((y,x)); comp=[]
        while stack:
          yy,xx=stack.pop(); comp.append((yy,xx))
          for ny,nx in ((yy+1,xx),(yy-1,xx),(yy,xx+1),(yy,xx-1)):
            if 0<=ny<h and 0<=nx<w and a[ny][nx]==c and (ny,nx) not in seen:
              seen.add((ny,nx)); stack.append((ny,nx))
        ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
        t,b,l,r=min(ys),max(ys),min(xs),max(xs)
        # Hollow rectangular frames; fill their interior according to parity.
        if b-t>=2 and r-l>=2:
          interior=[a[yy][xx] for yy in range(t+1,b) for xx in range(l+1,r)]
          if all(v==bg for v in interior) and all(any(yy==t and xx==xx0 for yy,xx in comp) for xx0 in range(l,r+1)):
            color=7 if (b-t-1)%2 and (r-l-1)%2 else 2
            for yy in range(t+1,b):
              for xx in range(l+1,r):
                if a[yy][xx]==bg:a[yy][xx]=color
    return a
